function render_footer(): void { ?></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.querySelectorAll('[data-confirm]').forEach(el=>el.addEventListener('click',e=>{if(!confirm(el.dataset.confirm))e.preventDefault()}));document.querySelectorAll('form').forEach(form=>{const radios=[...form.querySelectorAll('[data-catalog-choice]')];if(!radios.length)return;const update=()=>{const choice=radios.find(r=>r.checked)?.value;form.querySelectorAll('[data-catalog-section]').forEach(el=>{el.hidden=!!choice&&!el.dataset.catalogSection.split(',').includes(choice)})};radios.forEach(r=>r.addEventListener('change',update));update()});document.querySelectorAll('.modal').forEach(modal=>modal.addEventListener('shown.bs.modal',()=>modal.querySelector('[data-modal-autofocus]')?.focus()));document.querySelectorAll('[data-cumulative-classes]').forEach(group=>{const boxes=Array.from(group.querySelectorAll('input[type="checkbox"]'));const render=(changed=null)=>{boxes.forEach(box=>{box.disabled=false;box.closest('label')?.classList.remove('cumulative-class-inherited');box.removeAttribute('aria-readonly')});let base=-1;if(changed){const changedIndex=boxes.indexOf(changed);if(changed.checked)base=changedIndex;else boxes.slice(changedIndex+1).forEach(box=>box.checked=false)}if(base<0)base=boxes.findIndex(box=>box.checked);if(base<0)return;boxes.forEach((box,index)=>{if(index>base){box.checked=true;box.disabled=true;box.setAttribute('aria-readonly','true');box.closest('label')?.classList.add('cumulative-class-inherited')}})};render();boxes.forEach(box=>box.addEventListener('change',()=>render(box)))});</script></body></html><?php }

