<div data-cumulative-classes data-catalog-section="FI"><label class="form-label d-block">Rolloutklasse FI</label><?php foreach(fi_class_codes() as $c):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="technical[]" value="<?=$c?>" <?=in_array('technical:'.$c,$selected,true)?'checked':''?>> <?=$c?></label><?php endforeach;?></div><div data-cumulative-classes data-catalog-section="DSV"><label class="form-label d-block">Rolloutklasse DSV</label><?php foreach($dsvLevels as $level):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="dsv_class[]" value="<?=e($level['class_code'])?>" <?=in_array('dsv:'.$level['class_code'],$selected,true)?'checked':''?>> <?=e($level['class_label'])?></label><?php endforeach;?></div>
