<script>(()=>{const search=document.getElementById('catalog-search'),status=document.getElementById('catalog-status-filter');if(!search||!status)return;const filter=()=>{const query=search.value.trim().toLocaleLowerCase('de');document.querySelectorAll('[id^="catalog-panel-"]').forEach(panel=>{let panelCount=0;panel.querySelectorAll('[data-catalog-group]').forEach(group=>{let groupCount=0;group.querySelectorAll('[data-catalog-service]').forEach(service=>{const visible=(!query||service.dataset.search.includes(query))&&(status.value==='all'||service.dataset.status===status.value);service.hidden=!visible;if(visible){groupCount++;panelCount++;}});group.hidden=groupCount===0;const badge=group.querySelector('[data-group-count]');if(badge)badge.textContent=groupCount+' '+(groupCount===1?'Leistung':'Leistungen');});const empty=panel.querySelector('.catalog-no-results');if(empty)empty.hidden=panelCount!==0;const summary=panel.querySelector('[data-result-summary]');if(summary)summary.textContent=panelCount+' Leistung'+(panelCount===1?'':'en')+' angezeigt';const badge=document.querySelector('[data-bs-target="#'+panel.id+'"] [data-tab-count]');if(badge)badge.textContent=String(panelCount);});};[search,status].forEach(control=>control.addEventListener(control===search?'input':'change',filter));filter();})();</script><?php }

/** Katalog einer Leistung aus dem Formular: genau ein Anbieter (Bankfachlich/RV, FI oder DSV); Klassen anderer Kataloge entfallen. */
function posted_catalog_targets(PDO $db,int $id,string $name,?int $projectId,array &$functional,array &$technical,array &$dsvClasses): array {
    $target=post_string('provider_target');if(!in_array($target,['RV','FI','DSV'],true))throw new RuntimeException('Bitte den Katalog wählen: Bankfachlich, FI oder DSV.');
    if($target!=='RV')$functional=[];if($target!=='FI')$technical=[];if($target!=='DSV')$dsvClasses=[];
    if($taken=service_name_taken($db,$name,$target,$id,$projectId))throw new RuntimeException('Im Katalog '.catalog_type_label($target).' gibt es bereits eine Leistung „'.$taken['name'].'“'.(empty($taken['is_standard'])?' in diesem Projekt':'').'. Bitte einen anderen Namen wählen oder die vorhandene Leistung verwenden.');
    return [$target];
}

/** Auswahl des Katalogs im Editor: jede Leistung gehört genau einem Katalog. */
function render_catalog_choice(array $service): void {
    $current=(string)(((array)($service['provider_targets']??[]))[0]??'');?>
<div><label class="form-label d-block fw-semibold">Katalog / Anbieter</label><?php foreach(['RV'=>'Bankfachlich (Regionalverbände bzw. zentral durch das Projekt)','FI'=>'FI','DSV'=>'DSV'] as $target=>$label):?><label class="form-check form-check-inline"><input class="form-check-input" type="radio" name="provider_target" value="<?=$target?>" data-catalog-choice <?=$current===$target?'checked':''?> required> <?=e($label)?></label><?php endforeach;?>
<div class="form-text">Jede Leistung gehört genau einem Katalog. Gleiche Namen sind in verschiedenen Katalogen erlaubt, z. B. „Kickoff“ bankfachlich und „Kickoff“ der FI.</div></div>
<?php }

/** Grafik: Kombinationen aus Rolloutklasse Bankfachlich und den Klassen von FI bzw. DSV, mit Anzahl der Rolloutobjekte je Kombination. */
function render_class_combinations(PDO $db): void {
    $objects=enrich_rollout_objects($db,$db->query('SELECT * FROM rollout_objects')->fetchAll());$functional=['A','B','C','D'];
    $schemes=['FI'=>provider_class_levels($db,'FI',true),'DSV'=>provider_class_levels($db,'DSV',true)];$total=count($objects); ?>
<section class="card p-4" style="max-width:1300px"><h2 class="h5 mb-1">Kombinationsmöglichkeiten der Klassen</h2><p class="small text-secondary mb-3">Jedes Rolloutobjekt hat eine Rolloutklasse Bankfachlich (A–D) und je Verbunddienstleister eine eigene Klasse (0 = keine Verbundpartnerleistung). Alle Kombinationen sind zulässig. Die Zahl im Feld zeigt, wie viele Rolloutobjekte diese Kombination heute haben (<?=$total?> Rolloutobjekte insgesamt). Alle Klassen wirken kumulativ: Eine höhere Klasse enthält die Leistungen aller niedrigeren.</p>
<div class="row g-4"><?php foreach($schemes as $type=>$levels):$field=$type==='FI'?'fi_class_code':'dsv_class_code';$counts=[];$max=0;foreach($objects as $object){$f=(string)($object['functional_class']??'');$c=(string)($object[$field]??'');$counts[$f][$c]=($counts[$f][$c]??0)+1;}foreach($counts as $row)foreach($row as $n)$max=max($max,$n);?>
<div class="col-xl-6"><h3 class="h6">Bankfachlich × <?=$type?></h3><div class="table-responsive"><table class="table table-sm text-center align-middle combo-table mb-2"><thead><tr><th class="text-start">Bankfachlich ↓ / <?=$type?> →</th><?php foreach($levels as $level):?><th><?=e((string)$level['class_code']==='0'?'0':(string)$level['class_label'])?></th><?php endforeach;?></tr></thead><tbody>
<?php foreach($functional as $fIndex=>$f):?><tr><th class="text-start"><span class="class-chip">Klasse <?=$f?></span><div class="small fw-normal text-secondary">enthält <?=implode(', ',array_slice($functional,0,$fIndex+1))?></div></th><?php foreach($levels as $lIndex=>$level):$n=$counts[$f][(string)$level['class_code']]??0;$alpha=$max?0.12+0.68*$n/$max:0;$shade=$fIndex+$lIndex;?><td><div class="combo-cell <?=$n?'':'combo-empty'?>" style="<?=$n?'background:rgba(227,6,19,'.round($alpha,2).');color:'.($alpha>0.5?'#fff':'#252525'):''?>" title="Bankfachlich <?=$f?> mit <?=$type?> <?=e((string)$level['class_label'])?>: <?=$n?> Rolloutobjekt(e)"><span class="combo-code"><?=$f?> / <?=e((string)$level['class_code']==='0'?'0':(string)$level['class_label'])?></span><strong><?=$n?></strong></div></td><?php endforeach;?></tr><?php endforeach;?>
</tbody></table></div><?php $unclassified=0;foreach($objects as $object)if((string)($object['functional_class']??'')===''||(string)($object[$field]??'')==='')$unclassified++;if($unclassified):?><p class="small text-secondary mb-0"><?=$unclassified?> Rolloutobjekt(e) ohne vollständige Klassenangabe sind nicht enthalten.</p><?php endif;?></div>
<?php endforeach;?></div></section>
<?php }

function render_providers(PDO $db): void {$providers=providers_for_contacts($db);$contacts=provider_rollout_contacts($db);$groups=['Regionalverbände'=>array_values(array_filter($providers,fn($p)=>$p['type']==='RV')),'Dienstleister'=>array_values(array_filter($providers,fn($p)=>$p['type']!=='RV'))];
    $contactRow=static fn(int $providerId,string $index,string $name,string $email,string $providerName):string=>'<div class="input-group input-group-sm contact-row" data-contact-row><input class="form-control" name="provider['.$providerId.'][contacts]['.$index.'][name]" value="'.e($name).'" placeholder="Name" aria-label="Name Rollout-Ansprechpartner '.e($providerName).'"><input type="email" class="form-control" name="provider['.$providerId.'][contacts]['.$index.'][email]" value="'.e($email).'" placeholder="E-Mail-Adresse" aria-label="E-Mail-Adresse Rollout-Ansprechpartner '.e($providerName).'"><button type="button" class="btn btn-outline-secondary" data-contact-remove title="Ansprechpartner entfernen" aria-label="Ansprechpartner entfernen">×</button></div>';?>
<div class="mb-4"><h1 class="page-title h2 mb-1">Leistungserbringer</h1><p class="text-secondary mb-0">Rollout-Ansprechpartner sind die festen Ansprechpersonen eines Leistungserbringers für den Rollout insgesamt – unabhängig von den Ansprechpartnern, die je Projekt in der Projektmatrix gepflegt werden. Je Leistungserbringer sind beliebig viele möglich. Für größere Änderungen gibt es die Excel-Datei unter <a href="?page=exports#stammdaten">Export</a> bzw. <a href="?page=import#stammdaten">Import</a> (Stammdaten).</p></div><form method="post" class="vstack gap-4" style="max-width:1100px" data-track-dirty><?=csrf_field()?><input type="hidden" name="action" value="save_providers">
<?php foreach($groups as $groupTitle=>$groupProviders):?><section class="card p-4"><h2 class="h5 mb-1"><?=e($groupTitle)?></h2><p class="small text-secondary"><?=$groupTitle==='Regionalverbände'?'Alphabetisch geführt. Inaktive Regionalverbände erhalten keine Abfragedateien.':'Verbunddienstleister mit eigenem Leistungskatalog und Klassenschema. Weitere Dienstleister können später ergänzt werden.'?></p><div class="table-responsive"><table class="table align-middle mb-0 provider-table"><thead><tr><th style="width:20%"><?=$groupTitle==='Regionalverbände'?'Regionalverband':'Dienstleister'?></th><th>Rollout-Ansprechpartner <span class="fw-normal text-secondary small">· Name und E-Mail-Adresse</span></th><th class="text-center" style="width:1%">Aktiv</th></tr></thead><tbody><?php foreach($groupProviders as $p):$list=$contacts[(int)$p['id']]??[['name'=>'','email'=>'']];?><tr><td class="align-top"><input class="form-control" name="provider[<?=$p['id']?>][name]" value="<?=e($p['name'])?>" <?=$p['type']==='RV'?'':'readonly'?> required aria-label="Name"></td><td><div class="vstack gap-2" data-contact-list data-provider-id="<?=$p['id']?>" data-provider-name="<?=e($p['name'])?>"><?php foreach($list as $index=>$contact)echo $contactRow((int)$p['id'],(string)$index,$contact['name'],$contact['email'],(string)$p['name']);?></div><button type="button" class="btn btn-link btn-sm px-0 mt-1" data-contact-add>+ weiterer Ansprechpartner</button></td><td class="text-center align-top pt-3"><input class="form-check-input" type="checkbox" name="provider[<?=$p['id']?>][active]" <?=$p['active']?'checked':''?> aria-label="<?=e($p['name'])?> aktiv"></td></tr><?php endforeach;?><?php if(!$groupProviders):?><tr><td colspan="3" class="text-secondary">Keine Einträge vorhanden.</td></tr><?php endif;?></tbody></table></div></section><?php endforeach;?>
<button class="btn btn-primary align-self-start">Leistungserbringer speichern</button></form>
<template id="contact-row-template"><?=$contactRow(0,'__INDEX__','','','')?></template>
<script>(()=>{const tpl=document.getElementById('contact-row-template').innerHTML;let next=Date.now();const dirty=el=>el.closest('form')?.dispatchEvent(new Event('change',{bubbles:true}));
document.addEventListener('click',ev=>{const add=ev.target.closest('[data-contact-add]');if(add){const list=add.parentElement.querySelector('[data-contact-list]');const id=list.dataset.providerId;const html=tpl.replaceAll('provider[0]','provider['+id+']').replaceAll('__INDEX__','n'+(next++));list.insertAdjacentHTML('beforeend',html);list.lastElementChild.querySelector('input').focus();dirty(list);return;}
const remove=ev.target.closest('[data-contact-remove]');if(remove){const row=remove.closest('[data-contact-row]');const list=row.parentElement;if(list.querySelectorAll('[data-contact-row]').length>1)row.remove();else row.querySelectorAll('input').forEach(i=>i.value='');dirty(list);}});})();</script>
<?php }

