function render_import_confirmation(array $wizard): void {
    $changes=(array)($wizard['changes']??[]);$counts=['new'=>0,'change'=>0,'clear'=>0,'delete'=>0];foreach($changes as $change)$counts[$change['type']]++;
    $labels=['new'=>'Neu','change'=>'Geändert','clear'=>'Wird geleert','delete'=>'Wird entfernt'];$colors=['new'=>'success','change'=>'primary','clear'=>'warning','delete'=>'danger'];$source=in_array(($wizard['kind']??''),['catalog','contacts'],true)?(string)($wizard['source_file']??'Datei'):count((array)($wizard['files']??[])).' Datei(en)';?>
<div class="project-matrix-page"><div class="mb-4"><h1 class="page-title h2 mb-1">Geplante Änderungen bestätigen</h1><p class="text-secondary mb-0">Letzter Schritt · <?=e($source)?> · Noch wurde nichts gespeichert.</p></div>
<div class="alert alert-warning"><strong>Bitte kontrollieren:</strong> Erst der rote Bestätigungsbutton schreibt die unten aufgeführten Änderungen in die Datenbank. Nicht aufgeführte Daten bleiben unverändert.</div>
