<div class="alert alert-light border"><?=$mode==='feedback'?'Ordnen Sie jede Rückmeldedatei genau einem Leistungserbringer zu. Es werden nur vorhandene Projekte verwendet und ausschließlich dessen Angaben zu den Rolloutleistungen aktualisiert. Bereits importierte Rückmeldungen anderer Leistungserbringer bleiben erhalten.':($mode==='planning'?'Die Planungsdatei aktualisiert Rolloutdaten und Objektklassen sowie die von TPL/PL je Rolloutobjekt ausgewählten Rolloutleistungen. Eine Angebots- oder Bereitstellungsabfrage findet in dieser Phase nicht statt.':'Bitte kontrollieren Sie die erkannten Werte. Dieser Strukturimport darf neue Projekte und Rolloutobjekte anlegen.')?> Neue oder unklare Leistungen müssen vor der Übernahme zugeordnet, als zusätzliche Rolloutleistung angelegt oder ausgelassen werden.</div>
<?php $dbState=['objects'=>[],'byName'=>[],'usage'=>[],'matrix'=>[],'alwaysIncluded'=>[],'providerTypes'=>[],'classLabels'=>[]];foreach($providers as $providerRow)$dbState['providerTypes'][(int)$providerRow['id']]=(string)$providerRow['type'];foreach(['FI','DSV'] as $levelType)foreach(provider_class_levels($db,$levelType,true) as $level)$dbState['classLabels'][$levelType][(string)$level['class_code']]=(string)$level['class_label'];$matchKey=static fn(string $v):string=>import_match_key($v);
foreach($db->query('SELECT r.id,r.name,r.start_date,r.end_date,r.functional_class,r.notes,p.name project_name FROM rollout_objects r JOIN projects p ON p.id=r.project_id')->fetchAll() as $o){$dbState['objects'][(int)$o['id']]=['s'=>format_date($o['start_date'],''),'e'=>format_date($o['end_date'],''),'f'=>(string)($o['functional_class']??''),'n'=>(string)$o['notes']];$dbState['byName'][$matchKey((string)$o['project_name']).'|'.$matchKey((string)$o['name'])]=(int)$o['id'];}
