foreach($db->query('SELECT support_service_id,rollout_object_id,delivery_level FROM project_service_rollout_objects')->fetchAll() as $u)$dbState['usage'][$u['rollout_object_id'].':'.$u['support_service_id']]=(string)($u['delivery_level']??'');foreach($catalogMeta as $metaId=>$metaService)$dbState['delivery'][$metaId]=service_regional_capable($metaService)?service_effective_delivery($metaService):'';
foreach($db->query('SELECT id FROM support_services WHERE always_included=1')->fetchAll() as $svc)$dbState['alwaysIncluded'][(int)$svc['id']]=1;
if($mode==='feedback')foreach($db->query('SELECT project_id,support_service_id,provider_id,offered,delivery_mode,delivery_partner,schedule,note FROM project_support_matrix')->fetchAll() as $m)$dbState['matrix'][$m['project_id'].':'.$m['support_service_id'].':'.$m['provider_id']]=['o'=>$m['offered']?'Ja':'Nein','m'=>delivery_mode_label((string)$m['delivery_mode']),'pa'=>(string)$m['delivery_partner'],'s'=>(string)$m['schedule'],'n'=>(string)$m['note']];
if(!empty($wizard['replace'])):?><div class="alert alert-warning"><strong>„Datei ist maßgeblich“ ist aktiv.</strong> Am Rolloutobjekt eingetragene Leistungen, die in der Datei nicht genannt werden, werden entfernt (außer Leistungen mit „Immer enthalten“). Zeilen mit „Nicht übernehmen“ zählen dabei trotzdem als genannt und bleiben erhalten. Die Entfernungen sehen Sie im nächsten Schritt als „Wird entfernt“.</div><?php endif;?>
