/** Block der Darstellung: 0 Projekt (zentral), 1 Regionalverbände (regional), 2 FI, 3 DSV. */
function export_block_label(int $block): string {return ['Projekt (zentral)','Regionalverbände (regional)','FI','DSV'][$block]??'';}

/** Sortierschlüssel „ab Klasse“ im Katalog des Anbieters. */
function export_class_rank(array $service,string $providerType): string {$dimension=catalog_dimension($providerType);$codes=[];foreach((array)($service['class_codes']??[]) as $entry){[$d,$c]=array_pad(explode(':',(string)$entry,2),2,'');if($d===$dimension)$codes[]=$c;}sort($codes,SORT_NATURAL);return $codes[0]??'~';}

function export_data(PDO $db,string $format): never {
    sync_always_included_services($db);
    $rows=[array_merge(template_headers(),['Art des Leistungserbringers','Zuständig laut Katalog','Stand der Leistungserbringung','Leistung erbracht durch','Block'])];
    $objectStmt=$db->prepare('SELECT * FROM rollout_objects WHERE project_id=? ORDER BY start_date,name');
    $serviceStmt=$db->prepare("SELECT s.*,v.id provider_id,v.name provider_name,v.type provider_type,COALESCE(c.contact_name,'') contact_name,COALESCE(c.contact_phone,'') contact_phone,COALESCE(m.offered,0) offered,COALESCE(m.delivery_mode,'') delivery_mode,COALESCE(m.delivery_partner,'') delivery_partner,COALESCE(m.schedule,'') schedule,COALESCE(m.note,'') note,CASE WHEN m.provider_id IS NULL THEN 0 ELSE 1 END has_cell FROM project_services ps JOIN support_services s ON s.id=ps.support_service_id JOIN support_service_provider_targets t ON t.support_service_id=s.id JOIN providers v ON v.type=t.provider_type AND v.active=1 LEFT JOIN project_provider_contacts c ON c.project_id=ps.project_id AND c.provider_id=v.id LEFT JOIN project_support_matrix m ON m.project_id=ps.project_id AND m.support_service_id=s.id AND m.provider_id=v.id WHERE ps.project_id=? AND s.active=1 ORDER BY CASE t.provider_type WHEN 'RV' THEN 1 WHEN 'FI' THEN 2 ELSE 3 END,CASE WHEN t.provider_type='RV' THEN COALESCE((SELECT MIN(CASE c2.class_code WHEN 'A' THEN 1 WHEN 'B' THEN 2 WHEN 'C' THEN 3 WHEN 'D' THEN 4 ELSE 9 END) FROM support_service_classes c2 WHERE c2.support_service_id=s.id AND c2.dimension='functional'),9) ELSE COALESCE((SELECT MIN(CAST(c2.class_code AS INTEGER)) FROM support_service_classes c2 WHERE c2.support_service_id=s.id AND c2.dimension='technical'),9) END,s.name COLLATE NOCASE,v.name COLLATE NOCASE");
    foreach($db->query('SELECT * FROM projects ORDER BY name')->fetchAll() as $project){
        $rows[]=[$project['name'],'Projekt','','','','','',$project['project_lead'],$project['rollout_lead'],'','','','','','','','','','','',$project['description'],'','','','',''];$classScope=project_rollout_class_scope($db,(int)$project['id']);$projectClassObject=['functional_class'=>$classScope['functional']?$classScope['functional'][count($classScope['functional'])-1]:null,'fi_class_code'=>$classScope['technical']?$classScope['technical'][count($classScope['technical'])-1]:null,'dsv_class_code'=>$classScope['dsv']?$classScope['dsv'][count($classScope['dsv'])-1]:null];
        $objectStmt->execute([$project['id']]);foreach(enrich_rollout_objects($db,$objectStmt->fetchAll()) as $object)$rows[]=[$project['name'],'Rolloutobjekt',$object['name'],format_date($object['start_date'],''),format_date($object['end_date'],''),$object['functional_class'],($object['fi_class_code']??''),$project['project_lead'],$project['rollout_lead'],'','','','','','','','','','','',$object['notes'],'','','','',''];
        $serviceStmt->execute([$project['id']]);$exportServices=enrich_support_services($db,$serviceStmt->fetchAll());$deliveryMaps[(int)$project['id']]=project_service_delivery_map($db,(int)$project['id'],$exportServices);$objectNames=[];foreach($db->query('SELECT id,name FROM rollout_objects WHERE project_id='.(int)$project['id'])->fetchAll() as $objectRow)$objectNames[(int)$objectRow['id']]=(string)$objectRow['name'];$names=static fn(array $ids):string=>implode("\n",array_map(fn($id)=>$objectNames[$id]??'',$ids));$serviceRows=[];$centralDone=[];
        foreach($exportServices as $service){[$functional,$technical]=service_dimension_codes($service);$showDelivery=$service['provider_type']==='RV'&&!empty($service['requires_delivery_source']);$serviceDelivery=$deliveryMaps[(int)$project['id']][(int)$service['id']]??['rv_required'=>true,'regional'=>[],'central'=>[]];$isBank=$service['provider_type']==='RV'&&service_regional_capable($service);$rank=export_class_rank($service,$service['provider_type']);
            if($isBank&&($serviceDelivery['central']||!$serviceDelivery['rv_required'])&&!isset($centralDone[(int)$service['id']])){$centralDone[(int)$service['id']]=true;$serviceRows[]=[0,$rank,$service['name'],'',[$project['name'],'Rolloutleistung','','','','','',$project['project_lead'],$project['rollout_lead'],$service['name'],implode(', ',$functional),implode(', ',$technical),$serviceDelivery['central']?$names($serviceDelivery['central']):project_service_usage_names($db,(int)$project['id'],(int)$service['id']),'Projekt','','','Ja','','','','','Projekt',service_provider_summary($service),'Zentral durch das Projekt erbracht','Projekt','Projekt (zentral)']];}
            if($isBank&&!$serviceDelivery['rv_required'])continue;
            $row=[$project['name'],'Rolloutleistung','','','','','',$project['project_lead'],$project['rollout_lead'],$service['name'],implode(', ',$functional),implode(', ',$technical),$isBank&&$serviceDelivery['central']?$names($serviceDelivery['regional']):project_service_usage_names($db,(int)$project['id'],(int)$service['id']),$service['provider_name'],$service['contact_name'],$service['contact_phone'],$service['offered']?'Ja':'Nein',$showDelivery?delivery_mode_label((string)$service['delivery_mode']):'',$showDelivery?$service['delivery_partner']:'',!empty($service['schedule_relevant'])?$service['schedule']:'',$service['note'],['RV'=>'Regionalverband','FI'=>'FI','DSV'=>'DSV'][$service['provider_type']]??$service['provider_type']];
            $provision=service_provision_status($service,['id'=>$service['provider_id'],'type'=>$service['provider_type'],'name'=>$service['provider_name']],$service['has_cell']?['offered'=>$service['offered'],'delivery_mode'=>$service['delivery_mode'],'delivery_partner'=>$service['delivery_partner']]:null,service_applies_to_provider($service,['type'=>$service['provider_type']],$projectClassObject));
            $block=['RV'=>1,'FI'=>2,'DSV'=>3][$service['provider_type']]??4;array_push($row,service_provider_summary($service),$provision['label'],$provision['by'],export_block_label($block));$serviceRows[]=[$block,$rank,$service['name'],$service['provider_name'],$row];}
        usort($serviceRows,static fn($a,$b)=>$a[0]<=>$b[0]?:strnatcmp($a[1],$b[1])?:strnatcasecmp((string)$a[2],(string)$b[2])?:strnatcasecmp((string)$a[3],(string)$b[3]));foreach($serviceRows as $serviceRow)$rows[]=$serviceRow[4];
    }
    $filename='rollout-schwerpunkte-'.date('d.m.Y');
    if($format==='xlsx')Xlsx::download($rows,$filename.'.xlsx');
    header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");foreach($rows as $row)fputcsv($out,$row,';');fclose($out);exit;
}

function template_headers(): array {
    return ['Projekt','Datensatz','Rolloutobjekt','Rolloutbeginn','Rolloutende','Rolloutklasse Bankfachlich','Rolloutklasse Verbunddienstleister','Projektleitung','TPL Rollout','Unterstützungsleistung','Leistungsklasse Bankfachlich','Leistungsklasse Verbunddienstleister','Genutzt für Rolloutobjekte','Leistungserbringer','Ansprechpartner','Telefonnummer','Angeboten','Bereitstellungsart','Anderer Regionalverband / externer Dienstleister','Termin / Zeitraum','Bemerkung'];
}

function tpl_template_headers(bool $includeProviderData=true): array {
    $headers=['Projekt','Datensatz','Rolloutobjekt','Rolloutbeginn','Rolloutende','Rolloutklasse Bankfachlich'];
    if($includeProviderData)$headers[]='Rolloutklasse Verbunddienstleister';
    $headers[]='Katalogleistung Bankfachlich';
    if($includeProviderData)$headers[]='Katalogleistung Verbunddienstleister';
    array_push($headers,'Unterstützungsleistung außerhalb des Katalogs','Erbringung','Anmerkung zum Rolloutobjekt');
    return $headers;
}

function service_dimension_codes(array $service): array {
    $functional=[];$technical=[];$dsv=[];foreach((array)($service['class_codes']??[]) as $class){[$dimension,$code]=array_pad(explode(':',(string)$class,2),2,'');if($dimension==='functional')$functional[]=$code;if($dimension==='technical')$technical[]=$code;if($dimension==='dsv')$dsv[]=$code;}return [$functional,$technical,$dsv];
}

function project_service_usage_names(PDO $db,int $projectId,int $serviceId): string {
    $stmt=$db->prepare('SELECT r.name FROM project_service_rollout_objects u JOIN rollout_objects r ON r.id=u.rollout_object_id WHERE u.project_id=? AND u.support_service_id=? ORDER BY r.start_date,r.name COLLATE NOCASE');$stmt->execute([$projectId,$serviceId]);return implode("\n",array_column($stmt->fetchAll(),'name'));
}

/** Einheitliche, empfängerbezogene Legende für alle Excel-Arbeitsdateien. */
function export_legend(PDO $db,string $audience,bool $includeProviderData=true): array {
    $tasks=[
        'TPL'=>$includeProviderData?'Pflegen Sie je Rolloutobjekt die bankfachliche und die Verbunddienstleisterklasse und wählen Sie die aus Projektsicht vorgesehenen Unterstützungsleistungen. Angebot und Bereitstellung werden in dieser Phase noch nicht abgefragt.':'Pflegen Sie je Rolloutobjekt die bankfachliche Rolloutklasse und wählen Sie die aus Projektsicht vorgesehenen bankfachlichen Unterstützungsleistungen. Angaben der Verbunddienstleister sind in dieser Datei bewusst nicht enthalten.',
        'FI'=>'Wählen Sie je Rolloutobjekt die FI-Rolloutklasse und danach die dazu passenden Katalogleistungen. Klasse 0 bedeutet, dass keine FI-Unterstützungsleistung erforderlich ist; die Leistungsauswahl bleibt dann leer. Weitere Leistungen tragen Sie bei den Klassen 1–3 im Freitextfeld ein. Ergänzen Sie anschließend gegebenenfalls Termin oder Zeitraum sowie Bemerkungen.',
        'DSV'=>'Wählen Sie je Rolloutobjekt die DSV-Rolloutklasse und danach die dazu passenden Katalogleistungen. Klasse 0 bedeutet, dass keine DSV-Unterstützungsleistung erforderlich ist; die Leistungsauswahl bleibt dann leer. Bei den übrigen Klassen können Sie weitere Leistungen eintragen und als neue zentrale Katalogleistung vorschlagen.',
        'RV'=>'Geben Sie für die vorgesehenen Rolloutleistungen an, ob und wie Ihr Regionalverband sie bereitstellt. Bei den entsprechenden Leistungen wählen Sie eigene Bereitstellung, einen anderen Regionalverband, einen externen Dienstleister oder keine Bereitstellung. FI- und DSV-Angaben sind nur zur Information enthalten. Die Spalte „Erbracht durch“ zeigt je Leistung, wer sie laut Katalog erbringt: Nur bei bankfachlichen Leistungen mit dem Hinweis „Ihre Angabe erforderlich“ ist Ihre Rückmeldung nötig.',
    ];
    $standards=enrich_support_services($db,$db->query('SELECT * FROM support_services WHERE is_standard=1 AND active=1 ORDER BY name COLLATE NOCASE')->fetchAll());
    $rows=[
        ['type'=>'title','values'=>['Legende und Anleitung']],
        ['type'=>'note','values'=>['Ihre Aufgabe',$tasks[$audience]??$tasks['TPL']]],
        ['type'=>'note','values'=>['Ablauf','Phase 1: TPL/PL wählt die vorgesehenen Leistungen je Rolloutobjekt. Phase 2: FI und DSV ergänzen ihre geplanten Unterstützungen. Phase 3: Regionalverbände geben ihre Bereitstellungsart an.']],
        ['type'=>'note','values'=>['Rolloutklassen','Rolloutklassen werden ausschließlich am Rolloutobjekt gepflegt. Die höchste Klasse der Rolloutobjekte beschreibt den Umfang des Projekts.']],
    ];
    if($audience!=='TPL'||$includeProviderData)$rows[]=['type'=>'note','values'=>['Klasse 0 bei FI und DSV','Klasse 0 bedeutet: Für das Rolloutobjekt ist beim jeweiligen Verbundpartner keine Unterstützungsleistung erforderlich. Der Leistungskatalog enthält deshalb konsequent keine Leistungen der Klasse 0.']];
    $rows[]=['type'=>'note','values'=>['Kumulative Auswahl',($audience==='TPL'&&!$includeProviderData)?'Bankfachlich: A ist in B, C und D enthalten. In den Katalogdateien steht deshalb auch bei allen höheren Klassen „Ja“.':'Bankfachlich: A ist in B, C und D enthalten. FI: 1 ist in 2 und 3 enthalten. Beim DSV gilt dieselbe kumulative Logik in der unter „Leistungserbringer“ festgelegten Reihenfolge der Klassen. In den Katalogdateien steht deshalb auch bei allen höheren Klassen „Ja“.']];
    $rows[]=['type'=>'note','values'=>['Begriffe','Zentral erbrachte Leistungen werden nicht abgefragt, weil das Projekt sie selbst erbringt; abgefragt werden nur regional zu erbringende bankfachliche Leistungen. Termin oder Zeitraum wird nur bei dafür relevanten Leistungen gepflegt. Leistungen außerhalb des Katalogs werden beim Rückimport geprüft.']];
    $rows[]=['type'=>'blank','values'=>[]];
    $dsvLevels=provider_class_levels($db,'DSV');$dsvLabels=array_column($dsvLevels,'class_label','class_code');
    $definitions=[
        ['RV','Regionalverbände','functional',['A','B','C','D'],[]],
        ['FI','FI','technical',fi_class_codes(),[]],
        ['DSV','DSV','dsv',array_column($dsvLevels,'class_code'),$dsvLabels],
    ];
    foreach($definitions as [$target,$label,$dimension,$classes,$classLabels]){
        if($audience==='TPL'&&!$includeProviderData&&$target!=='RV')continue;
        $rows[]=['type'=>'section','values'=>[$label]];
        $rows[]=['type'=>'header','values'=>['Klasse','Unterstützungsleistung','Zuständigkeit','']];
        foreach($classes as $class){
            $items=[];
            foreach($standards as $service){
                if(!in_array($target,(array)$service['provider_targets'],true))continue;
                [$functional,$technical,$dsv]=service_dimension_codes($service);
                $codes=$dimension==='functional'?$functional:($dimension==='dsv'?$dsv:$technical);
                if(in_array($class,$codes,true))$items[]=$service;
            }
            usort($items,static fn(array $a,array $b):int=>strnatcasecmp((string)$a['name'],(string)$b['name']));
            $displayClass=(string)($classLabels[$class]??$class);foreach($items as $service)$rows[]=['type'=>'catalog','dimension'=>$dimension,'class'=>$class,'values'=>[$displayClass,(string)$service['name'],$label,'']];
        }
        $rows[]=['type'=>'blank','values'=>[]];
    }
    return ['rows'=>$rows];
}

function tpl_template_workbook(PDO $db,int $onlyProjectId=0,bool $includeProviderData=false): array {
    $standards=enrich_support_services($db,$db->query('SELECT * FROM support_services WHERE is_standard=1 AND active=1 ORDER BY name COLLATE NOCASE')->fetchAll());
    $functionalOrder=['A','B','C','D'];$technicalOrder=fi_class_codes();
    $sortServices=static function(array &$services):void{usort($services,static fn(array $a,array $b):int=>strnatcasecmp((string)$a['name'],(string)$b['name']));};
    $sortForDimension=static function(array &$services,string $dimension,array $order):void{usort($services,static function(array $a,array $b)use($dimension,$order):int{$rank=static function(array $service)use($dimension,$order):int{$codes=[];foreach((array)($service['class_codes']??[]) as $entry){[$entryDimension,$code]=array_pad(explode(':',(string)$entry,2),2,'');if($entryDimension===$dimension)$codes[]=$code;}$positions=array_filter(array_map(static fn(string $code):int|false=>array_search($code,$order,true),$codes),static fn(int|false $position):bool=>$position!==false);return $positions?min($positions):99;};return ($rank($a)<=>$rank($b))?:strnatcasecmp((string)$a['name'],(string)$b['name']);});};
    $lists=['RV_EMPTY'=>[''],'VD_EMPTY'=>[''],'VD_0'=>['']];
    foreach($functionalOrder as $class){$allowed=cumulative_functional_classes($class);$items=[];foreach($standards as $service){[$functional]=service_dimension_codes($service);if(in_array('RV',(array)$service['provider_targets'],true)&&array_intersect($functional,$allowed))$items[(int)$service['id']]=$service;}$sortForDimension($items,'functional',$functionalOrder);$lists['RV_'.$class]=array_values(array_map(static fn(array $service):string=>(string)$service['name'],$items));if(!$lists['RV_'.$class])$lists['RV_'.$class]=[''];}
    foreach($technicalOrder as $class){$allowed=cumulative_technical_classes($class);$items=[];foreach($standards as $service){[, $technical]=service_dimension_codes($service);if(array_intersect(['FI','DSV'],(array)$service['provider_targets'])&&array_intersect($technical,$allowed))$items[(int)$service['id']]=$service;}$sortForDimension($items,'technical',$technicalOrder);$lists['VD_'.$class]=array_values(array_map(static fn(array $service):string=>(string)$service['name'],$items));if(!$lists['VD_'.$class])$lists['VD_'.$class]=[''];}

    $legend=export_legend($db,'TPL',$includeProviderData);

    $rows=[tpl_template_headers(true)];$validationRows=[];
    $objectStmt=$db->prepare('SELECT * FROM rollout_objects WHERE project_id=? ORDER BY start_date,name');
    $serviceStmt=$db->prepare('SELECT s.* FROM project_services ps JOIN support_services s ON s.id=ps.support_service_id WHERE ps.project_id=? AND s.active=1 ORDER BY s.name COLLATE NOCASE');
    $usageStmt=$db->prepare('SELECT support_service_id,delivery_level FROM project_service_rollout_objects WHERE project_id=? AND rollout_object_id=?');
    $projectQuery=$onlyProjectId?'SELECT * FROM projects WHERE id='.(int)$onlyProjectId:'SELECT * FROM projects ORDER BY name';
    foreach($db->query($projectQuery)->fetchAll() as $project){
        $serviceStmt->execute([$project['id']]);$projectServices=[];foreach(enrich_support_services($db,$serviceStmt->fetchAll()) as $service)$projectServices[(int)$service['id']]=$service;
        $objectStmt->execute([$project['id']]);$objects=enrich_rollout_objects($db,$objectStmt->fetchAll());
        foreach($objects as $object){
            $rows[]=[(string)$project['name'],'Rolloutobjekt',(string)$object['name'],format_date($object['start_date'],''),format_date($object['end_date'],''),(string)$object['functional_class'],(string)(($object['fi_class_code']??'')),'','','','',(string)$object['notes']];
            $masterExcelRow=count($rows);
            $usageStmt->execute([(int)$project['id'],(int)$object['id']]);$usageRows=$usageStmt->fetchAll();$selectedIds=array_map('intval',array_column($usageRows,'support_service_id'));$usageLevels=array_column($usageRows,'delivery_level','support_service_id');$functionalLevels=[];
            $selectedFunctional=[];$selectedTechnical=[];$selectedOutside=[];
            foreach($selectedIds as $serviceId){if(!isset($projectServices[$serviceId]))continue;$service=$projectServices[$serviceId];[$functional,$technical]=service_dimension_codes($service);$targets=(array)$service['provider_targets'];$catalog=service_catalog_type($service)??($targets[0]??'RV');if($catalog==='DSV'||($catalog==='FI'&&!$includeProviderData))continue;if($catalog==='FI'&&!empty($service['is_standard'])&&!service_applies_to_rollout_object($service,$object))continue;if(!empty($service['is_standard'])&&in_array('RV',$targets,true)&&array_intersect($functional,cumulative_functional_classes((string)$object['functional_class']))){$selectedFunctional[]=(string)$service['name'];$functionalLevels[(string)$service['name']]=service_effective_delivery($service,$usageLevels[$serviceId]??null)==='central'?'zentral':'regional';}elseif(!empty($service['is_standard'])&&array_intersect(['FI','DSV'],$targets)&&array_intersect($technical,cumulative_technical_classes((string)(($object['fi_class_code']??'')))))$selectedTechnical[]=(string)$service['name'];else$selectedOutside[]=(string)$service['name'];}
            natcasesort($selectedFunctional);natcasesort($selectedTechnical);natcasesort($selectedOutside);$selectedFunctional=array_values($selectedFunctional);$selectedTechnical=array_values($selectedTechnical);$selectedOutside=array_values($selectedOutside);
            $slotCount=max(8,count($selectedFunctional),count($selectedTechnical),count($selectedOutside));
            for($slot=0;$slot<$slotCount;$slot++){$rows[]=['','Leistungsauswahl','','','','','',$selectedFunctional[$slot]??'',$selectedTechnical[$slot]??'',$selectedOutside[$slot]??'',isset($selectedFunctional[$slot])?($functionalLevels[$selectedFunctional[$slot]]??''):'',''];$validationRows[count($rows)]=['master_row'=>$masterExcelRow];}
        }
    }
    if(count($rows)===1)throw new RuntimeException('Es sind noch keine Rolloutobjekte vorhanden.');
    if(!$includeProviderData){foreach($rows as &$row){unset($row[6],$row[8]);$row=array_values($row);}unset($row);$lists=array_filter($lists,static fn(string $name):bool=>str_starts_with($name,'RV_'),ARRAY_FILTER_USE_KEY);}
    return ['rows'=>$rows,'legend'=>$legend,'lists'=>$lists,'validation_rows'=>$validationRows];
}

/** Phase 2: FI bzw. DSV wählen ihre geplanten Leistungen je Rolloutobjekt. */
function central_provider_template_workbook(PDO $db,array $provider): array {
    if(!in_array((string)$provider['type'],['FI','DSV'],true))throw new RuntimeException('Diese Vorlage ist nur für FI oder DSV vorgesehen.');
    sync_always_included_services($db);
    $type=(string)$provider['type'];$levels=provider_class_levels($db,$type,true);if(!$levels)throw new RuntimeException('Für '.$type.' ist kein Klassenschema hinterlegt.');$dimension=$type==='DSV'?'dsv':'technical';
    $standards=enrich_support_services($db,$db->query('SELECT * FROM support_services WHERE is_standard=1 AND active=1 ORDER BY name COLLATE NOCASE')->fetchAll());
    $lists=[$type.'_EMPTY'=>[''],$type.'_CLASS'=>array_column($levels,'class_label')];$allowedCodes=[];
    foreach($levels as $index=>$level){$allowedCodes[]=(string)$level['class_code'];$items=[];foreach($standards as $service){$serviceCodes=[];foreach((array)$service['class_codes'] as $entry){[$entryDimension,$code]=array_pad(explode(':',(string)$entry,2),2,'');if($entryDimension===$dimension)$serviceCodes[]=$code;}if(in_array($type,(array)$service['provider_targets'],true)&&array_intersect($serviceCodes,$allowedCodes))$items[(int)$service['id']]=$service;}usort($items,static fn(array $a,array $b):int=>strnatcasecmp((string)$a['name'],(string)$b['name']));$lists[$type.'_L'.($index+1)]=array_values(array_map(static fn(array $service):string=>(string)$service['name'],$items));if(!$lists[$type.'_L'.($index+1)])$lists[$type.'_L'.($index+1)]=[''];}
    $headers=['Projekt','Datensatz','Rolloutobjekt','Rolloutbeginn','Rolloutende','Rolloutklasse '.$type,'Katalogleistung '.$type,'Unterstützungsleistung außerhalb des Katalogs'];
