function import_state_hash(PDO $db): string {return hash('sha256',serialize(import_state_snapshot($db)));}

function compare_import_states(array $before,array $after): array {
    $changes=[];$keys=array_values(array_unique(array_merge(array_keys($before),array_keys($after))));sort($keys);
    foreach($keys as $key){$old=$before[$key]??null;$new=$after[$key]??null;if($old===null){$changes[]=['type'=>'new','category'=>$new['category'],'subject'=>$new['subject'],'field'=>'Neuer Datensatz','old'=>'','new'=>implode(' · ',array_filter(array_map(static fn($name,$value):string=>$value!==''?$name.': '.$value:'',array_keys($new['fields']),$new['fields'])))];continue;}if($new===null){$changes[]=['type'=>'delete','category'=>$old['category'],'subject'=>$old['subject'],'field'=>'Datensatz oder Zuordnung','old'=>implode(' · ',array_filter(array_map(static fn($name,$value):string=>$value!==''?$name.': '.$value:'',array_keys($old['fields']),$old['fields']))),'new'=>'','origin'=>$old['origin']??''];continue;}$fields=array_values(array_unique(array_merge(array_keys($old['fields']),array_keys($new['fields']))));foreach($fields as $field){$oldValue=(string)($old['fields'][$field]??'');$newValue=(string)($new['fields'][$field]??'');if($oldValue!==$newValue)$changes[]=['type'=>$newValue===''?'clear':'change','category'=>$new['category'],'subject'=>$new['subject'],'field'=>$field,'old'=>$oldValue,'new'=>$newValue,'origin'=>$old['origin']??''];}}
    return $changes;
}

/** Gleichnamige Leistungen verschiedener Kataloge am selben Rolloutobjekt als lesbare Zeilen (alle Projekte). */
function duplicate_lines(PDO $db): array {
    $lines=[];$objects=[];foreach($db->query('SELECT r.id,r.name,p.name project_name FROM rollout_objects r JOIN projects p ON p.id=r.project_id')->fetchAll() as $o)$objects[(int)$o['id']]=$o['project_name'].' / '.$o['name'];$names=array_column($db->query('SELECT id,name FROM support_services')->fetchAll(),'name','id');
    foreach($db->query('SELECT id FROM projects')->fetchAll(PDO::FETCH_COLUMN) as $projectId)foreach(duplicate_service_names($db,(int)$projectId) as $objectId=>$services){$groups=[];foreach(array_keys($services) as $serviceId)$groups[mb_strtolower(trim((string)($names[$serviceId]??'')))][]=$serviceId;foreach($groups as $serviceIds){$catalogs=[];foreach($serviceIds as $serviceId)$catalogs=array_merge($catalogs,$services[$serviceId]);$catalogs=array_values(array_intersect(['Bankfachlich','FI','DSV'],array_unique($catalogs)));$lines[]=($objects[$objectId]??'').': „'.trim((string)$names[$serviceIds[0]]).'“ – '.implode(', ',$catalogs);}}
    sort($lines);return array_values(array_unique($lines));
}

function simulate_import_changes(PDO $db,callable $runner): array {
    $before=import_state_snapshot($db);$stateHash=hash('sha256',serialize($before));$duplicatesBefore=duplicate_lines($db);$db->beginTransaction();try{$result=$runner();$after=import_state_snapshot($db);$duplicatesAfter=duplicate_lines($db);$db->rollBack();}catch(Throwable $error){if($db->inTransaction())$db->rollBack();throw $error;}return ['changes'=>compare_import_states($before,$after),'result'=>$result,'state_hash'=>$stateHash,'duplicates'=>array_values(array_diff($duplicatesAfter,$duplicatesBefore))];
}

/** Spalten der RV-Abfragedatei: vorne die Angaben des Regionalverbands, dahinter Informationen. */
function rv_template_headers(): array {
    return ['Projekt','Datensatz','Rolloutleistung','Leistungsklasse','Genutzt für Rolloutobjekte','Erbringung (Information)','Bereitstellungsart','Anderer Regionalverband / externer Dienstleister','Termin / Zeitraum','Bemerkung','Ansprechpartner','Telefonnummer','Erbracht durch','Block','FI-Planung (Information)','DSV-Planung (Information)','Leistungserbringer','Projektleitung','TPL Rollout','Nur Information','Leistung-ID'];
}

/** Leistungsklasse im eigenen Katalog, z. B. „A“, „FI 1“ oder „DSV Klasse 2“. */
function service_class_text(array $service,array $dsvLabels): string {
    [$functional,$technical,$dsv]=service_dimension_codes($service);$type=service_catalog_type($service)??((array)$service['provider_targets'])[0]??'RV';
    sort($functional,SORT_NATURAL);sort($technical,SORT_NATURAL);sort($dsv,SORT_NATURAL);
    if($type==='FI')return $technical?'FI '.$technical[0]:'';
    if($type==='DSV')return $dsv?'DSV '.(string)($dsvLabels[$dsv[0]]??$dsv[0]):'';
    return $functional[0]??'';
}

/** Rolloutobjekte je Projektname für die Auswahlliste „Genutzt für Rolloutobjekte“ der RV-Datei. */
function rv_object_lists(PDO $db): array {
    $lists=[];foreach($db->query('SELECT p.name project_name,r.name FROM rollout_objects r JOIN projects p ON p.id=r.project_id ORDER BY p.name,r.start_date,r.name')->fetchAll() as $row)$lists[(string)$row['project_name']][]=(string)$row['name'];return $lists;
}

/** Abfragedatei für einen Regionalverband (Rückimport über die Spaltenüberschriften). */
function provider_template_rows(PDO $db,array $provider): array {
    sync_always_included_services($db);$headers=rv_template_headers();$rows=[$headers];$width=count($headers);
    $dsvLabels=array_column(provider_class_levels($db,'DSV',true),'class_label','class_code');
